namespace docking.widgets.filter;

/**
 * A filter factory that creates {@link TextFilter}s that will pass text when it matches
 * the filter exactly.
 */
public class MatchesExactlyTextFilterFactory : TextFilterFactory {

	private bool caseSensitive;
	private bool allowGlobbing;

	public MatchesExactlyTextFilterFactory(bool caseSensitive, bool allowGlobbing) {
		this.caseSensitive = caseSensitive;
		this.allowGlobbing = allowGlobbing;
	}

	/* @Override */
	public TextFilter getTextFilter(string text) {
		if ((text == null) || (text.length() == 0)) {
			return null;
		}

		return new MatchesExactlyTextFilter(text, caseSensitive, allowGlobbing);
	}
}
